      "本人と妻に支払われる給付金の合計を、税引前で求める。診断・入院・手術・死亡の各給付は独立して全額支払われ、他の給付との相殺や減額はない。既払給付、他契約、税金、費用は考慮しない。これは設例固有の契約条件であり、実在商品に共通する保障ではない。"
