      "evidence": "会社員の安藤さん（1982年2月2日生まれ、死亡日現在44歳）は妻（42歳）と子2人を生計維持している。子は全員18歳到達年度末前、未婚、障害なし。安藤さんは厚生年金被保険者として死亡したものとし、保険料納付・遺族の収入等の受給要件はすべて満たす。厚生年金期間は2003年3月以前36月・平均標準報酬月額240,000円、同年4月以後240月・平均標準報酬額380,000円。2026年度価額の遺族基礎年金本体847,300円、子の加算は第1・2子各243,800円、第3子以後各81,300円。報酬比例乗率は順に7.125/1000、5.481/1000。遺族厚生年金は300月未満を300月とみなす短期要件で計算し、最終額のみ円未満四捨五入。従前額保障・中高齢寡婦加算等は今回の対象外。死亡日は2026年4月1日とし、加入記録は2026年3月までで、平均報酬は計算用に再評価済みの額とする。遺族基礎年金は子のある妻の本体と子加算の年額を計算し、初年度の月割支給額ではない。実加入期間が300月以上なら300月への増額調整はせず、300月未満の場合のみ300月みなしを適用する。2028年以後の遺族年金改正や子が年齢要件を外れた後の加算等は対象外。傷病手当金の設問は死亡の仮定とは別の会社員一般の制度確認である。 加入記録の具体的な期間は、2000年4月から2003年3月まで厚生年金（2003年3月以前）、2003年4月から2006年3月まで国民年金第1号の納付済、2006年4月から2026年3月まで厚生年金（2003年4月以後）。各期間は両端の月を含み、重複や記載以外の期間はない。最初の厚生年金加入時は18歳であり、20歳前の厚生年金期間も遺族厚生年金の実加入期間に含む。第1号納付済期間は厚生年金の実加入期間には加えない。2026年4月1日の死亡時まで最後の厚生年金加入は継続しており、年金計算に用いる2026年3月までの実加入は276月である。"
