    "sourceText": "個人事業主の遠藤さんの2026年分の事業所得（青色申告特別控除後）は840万円。国内の通常の賃貸物件に係る不動産所得は赤字60万円、そのうち土地取得借入金の利子15万円が必要経費に含まれる。組合・国外中古建物等の特例はない。本人負担の10年超保有の生命保険を解約し、一時金610万円、正味払込保険料510万円。他の一時所得はない。記載の事業所得・不動産所得・解約一時金以外の所得はない。対象医療費52万円を本人が支払い、その同じ医療費を補填する給付金14万円、補填超過なし。生計を一にする長女は年末21歳、無収入、障害なし、事業専従者ではない。2027年に行う2026年分の確定申告の場面とし、長女は国内居住で、他に長女を扶養控除の対象とする者はない。2026年12月1日施行で2026年分から適用される扶養所得要件62万円以下を用い、施行前準確定申告等は対象外とする。生命保険の実際の全額保険料負担者と解約一時金受取人はいずれも本人で、金融類似商品の源泉分離課税には該当しない。事業所得は青色申告特別控除後の与件で再度控除しない。医療費は自己/生計同一家族のため本人がその年中に実際に支払った対象費用とする。",
    "organization": "kinzai",
