      "evidence": "飲食店を営む渡辺さんは2026年4月1日現在51歳で、国民年金第1号被保険者である。2026年3月までの20歳以上の記録は、厚生年金180月、国民年金第1号の納付済132月、未納60月で、免除期間はない。厚生年金は2003年3月以前60月・平均標準報酬月額220,000円、同年4月以後120月・平均標準報酬額300,000円である。2026年4月から60歳到達までの108月は国民年金保険料をすべて納めるものとし、60歳時の納付済相当期間は420月となる。老齢基礎年金は2026年度の満額847,300円を固定して見積もり、将来の年金額改定、任意加入、繰上げ・繰下げは考慮しない。報酬比例部分の乗率は順に7.125/1000、5.481/1000とし、再評価済みの報酬を用いる。経過的加算・加給年金は計算対象外とする。小規模企業共済の加入要件を満たし、2026年中に本人が掛金を支払った。"
