      "飲食店を営む渡辺さん（1975年4月2日生まれ）は2026年4月1日現在51歳で、国民年金第1号被保険者である。",
      "2026年3月までの20歳以上の記録は、厚生年金180月、国民年金第1号の納付済132月、未納60月で、免除期間はない。",
