      "2026年4月から60歳到達までの108月は国民年金保険料をすべて納めるものとし、60歳時の納付済相当期間は420月となる。",
      "老齢基礎年金は2026年度の満額847,300円を固定して見積もり、将来の年金額改定、任意加入、繰上げ・繰下げは考慮しない。",
