      "小規模企業共済の加入要件を満たし、2026年中に本人が掛金を支払った。",
      " 年齢は誕生日の前日に到達するものとして扱い、20歳到達日は1995年4月1日、60歳到達日は2035年4月1日とする。",
      "加入記録の具体的な期間は、1995年4月から1998年3月まで国民年金第1号の未納、1998年4月から2003年3月まで厚生年金（2003年3月以前）、2003年4月から2013年3月まで厚生年金（2003年4月以後）、2013年4月から2024年3月まで国民年金第1号の納付済、2024年4月から2026年3月まで国民年金第1号の未納、2026年4月から2035年3月まで国民年金第1号の将来納付見込み。",
      "各期間は両端の月を含み、重複やこれ以外の加入・未納期間はない。"
