      "evidence": "東雲社は非上場の同族会社である。税務評価上の資産・負債と評価差額に対する法人税額等相当額を反映済みの純資産価額総額は18,000万円、発行済株式数は100,000株で、自己株式はない。本問では与えられた調整後純資産価額を発行済株式数で除す純資産価額方式だけを用い、80％評価、類似業種比準方式との併用、端数処理は行わない。会社の株式には譲渡制限があり、取締役会設置会社で、譲渡承認機関について定款の別段の定めはない。社長の推定相続人は法律上の妻と実子2人の計3人で、相続放棄、養子、代襲相続、相続欠格・廃除はない。"
