      "evidence": "会社員の佐藤さん（1965年7月2日生まれ）は、2026年4月1日現在の制度で妻と母の生活も含めた老後資金を相談している。20歳以上60歳未満の納付済相当期間は432月で、480月との差は未納期間とする。免除期間の加算や任意加入の扱いはない。厚生年金の計算資料は、2003年3月以前72月・平均標準報酬月額250,000円、2003年4月以後276月・平均標準報酬額360,000円で、記録は2026年3月までのものとする。上記の平均報酬は2026年度の計算用に再評価済みの額で、さらに再評価率を掛けない。65歳からの年金年額を2026年度価額で試算し、基礎年金満額847,300円、報酬比例乗率は順に7.125/1000、5.481/1000を用いる。従前額保障・経過的加算・加給年金・在職による支給停止・繰上げ繰下げ・今後の加入による増額は計算対象外。将来の改定額や受給開始初年度の月割支給額は予測せず、与件の年額を求め、円未満は合計後に四捨五入する。母の介護のために介護休業を取得することも検討中で、本人は雇用保険の被保険者である。母は介護休業給付の対象家族であり、要介護状態・被保険者期間・就労日数等の支給要件を満たすものとする。本問は同じ対象家族についての支給限度日数・回数・原則の給付率を問い、賃金支払いによる調整・賃金日額の上下限額・申請実務は計算対象外とする。 加入記録の具体的な期間は、1985年7月から1989年6月まで国民年金第1号の未納、1989年7月から1997年3月まで国民年金第1号の納付済、1997年4月から2003年3月まで厚生年金（2003年3月以前）、2003年4月から2026年3月まで厚生年金（2003年4月以後）。各期間は両端の月を含み、重複や記載以外の期間はない。60歳到達日は2025年7月1日であり、その前月までの480月から未納期間を除いた432月を老齢基礎年金に用いる。60歳以後の厚生年金9月はこの基礎年金月数に加えず、報酬比例部分は指定した全厚生年金期間で計算する。2026年4月1日現在も厚生年金・雇用保険の被保険者として勤務しているが、年金試算の加入記録は同年3月までで固定する。"
