    "sourceText": "中村さんの相続人は妻と子2人の3人。本人負担の保険料に係る死亡保険金2400万円を相続人だけが受領した。これ以外の相続財産の課税価格は10000万円。債務・葬式費用・贈与加算・小規模宅地特例はない。相続税速算表（取得金額：税率／控除）は、1,000万円以下10％／0、3,000万円以下15％／50万円、5,000万円以下20％／200万円、1億円以下30％／700万円。配偶者の税額軽減など個別税額控除前の相続税の総額を求める。相続開始日は2026年4月1日とし、妻は法律上の配偶者、子2人はいずれも実子で、放棄・養子・代襲はない。保険料は全額を被相続人が負担し、被保険者も被相続人本人で、死亡保険金は一時金とする。配偶者と子の法定相続分で税額を計算する段階と、実際の取得割合で按分し各税額控除を適用する段階を区別する。最後の課税区分問題の別契約はこの課税価格へ加算しない。",
    "organization": "kinzai",
    "inputRows": [
      [
        "基準日・相続開始日",
        "2026年4月1日"
      ],
      [
        "法定相続人",
        "法律上の妻・実子2人。放棄等なし"
      ],
      [
        "死亡保険金（一時金）",
        "2400万円"
      ],
      [
        "死亡保険の負担者・被保険者",
        "いずれも被相続人本人"
      ],
      [
        "受取人",
        "相続人のみ"
      ],
      [
        "死亡保険金以外の課税価格",
        "10000万円"
      ],
      [
        "債務・葬式費・贈与加算・宅地特例",
        "なし"
      ],
      [
        "計算する税額",
        "法定相続分による相続税総額。配偶者軽減等の前"
      ],
      [
        "別契約の課税区分問題",
        "本設例の課税価格には加算しない"
      ]
    ],
    "sentences": [
      "中村さんの相続人は妻と子2人の3人。",
      "本人負担の保険料に係る死亡保険金2400万円を相続人だけが受領した。",
      "これ以外の相続財産の課税価格は10000万円。",
      "債務・葬式費用・贈与加算・小規模宅地特例はない。",
      "相続税速算表（取得金額：税率／控除）は、1,000万円以下10％／0、3,000万円以下15％／50万円、5,000万円以下20％／200万円、1億円以下30％／700万円。",
      "配偶者の税額軽減など個別税額控除前の相続税の総額を求める。",
      "相続開始日は2026年4月1日とし、妻は法律上の配偶者、子2人はいずれも実子で、放棄・養子・代襲はない。",
      "保険料は全額を被相続人が負担し、被保険者も被相続人本人で、死亡保険金は一時金とする。",
      "配偶者と子の法定相続分で税額を計算する段階と、実際の取得割合で按分し各税額控除を適用する段階を区別する。",
      "最後の課税区分問題の別契約はこの課税価格へ加算しない。"
    ],
