      "今回の退職金の計算対象となる勤務期間は全て役員としての期間で、2001年10月1日から2026年4月30日までの24年7か月とする。",
      "同日の退任に伴って会社から支払われる退職手当は、源泉徴収前の収入金額で2,300万円である。",
