      "還付申告・準確定申告・災害による延長や休日による期限移動などの特例は考えない。表の最高控除額は所得金額による上限の適用前であり、所得が不足すると実際の控除額は少なくなる。",
      "最高55万円の控除には、事業所得または事業的規模の不動産所得、正規の簿記、貸借対照表・損益計算書の添付と期限内申告などの要件がある。現金主義の特例を選択する場合は対象外である。",
      "最高65万円には55万円の要件に加え、期限内にe-Taxで申告書と必要な決算書を送信するか、仕訳帳・総勘定元帳を優良な電子帳簿の要件で備付け・保存し所定の届出要件を満たすことが必要である。電子保存だけで自動的に65万円にはならない。"
