      "保険契約は有効で、示した事故について他の免責はない。問うのは建物に生じた直接の損害に対する補償であり、地震火災費用保険金など別の費用補償の支払可否は判定しない。家財や自動車、第三者への賠償責任は本資料の対象外である。"
