      "evidence": "自営業の安藤さん（男性、1981年2月2日生まれ）は、2026年4月1日現在45歳で、配偶者と子はいない。厚生年金の加入実績は1999年4月から2024年3月までの300月で、このうち20歳前の1999年4月〜2001年1月が22月、20歳以上の2001年2月〜2024年3月が278月である。2003年3月以前の48月の平均標準報酬月額は240,000円、2003年4月以後の252月の平均標準報酬額は420,000円で、いずれも計算用に再評価済みの額とする。退職後の2024年4月〜2025年3月は国民年金第1号の未納12月で、免除・猶予・学生納付特例ではない。2025年4月〜2026年3月は第1号として12月納付済みであり、2026年4月〜2041年1月の178月も第1号として全額納付する見込みとする。各期間は両端の月を含み、重複も他の加入期間もない。60歳到達は2041年2月1日、65歳到達は2046年2月1日で、2024年4月以後は厚生年金に再加入しないものとする。問1は2026年4月1日の制度と2026年度価額を固定した将来仮定の計算であり、2046年度の実際の支給額を予測するものではない。計算用の老齢基礎年金満額は847,300円、定額部分の単価は1,766円、生年月日に応じた率は1.000、報酬比例乗率は7.125/1000と5.481/1000とする。問1では本来水準の報酬比例部分と経過的加算だけを老齢厚生年金に含め、従前額保障・再評価率の再計算・加給年金・振替加算・基金の代行・在職支給停止・繰上げ繰下げ・付加年金は計算しない。60歳以後の任意加入や未納分の後納も加えない。問2・問3は2026年4月1日の制度を固定した別々の検討である。問2③の付加保険料納付と問3の国民年金基金加入は同時に行う仮定ではなく、問1の年金額に加算しない。"
