    "sourceText": "遠藤さんは、2024年6月15日に死亡した母の一戸建て家屋と敷地を、唯一の相続人として全部取得した。相続直前まで母だけがその家で暮らしていた。家屋は1979年5月10日建築で、区分所有建物登記はない。敷地は東西20m・南北24mの長方形480㎡で、北側全幅が幅員6mの公道、東側全長が幅員5mの公道に接する。土地は近隣商業地域、指定建蔽率80％・指定容積率400％、準防火地域である。耐火建築物を建てる計画とし、防火性能による10ポイントと、特定行政庁指定の角地による10ポイントの建蔽率加算の要件を満たす。容積率はこの2道路の最大幅員6mに係数6/10を乗じた限度と指定容積率の小さい方を使う。道路後退・隅切りによる面積減少・特定道路による割増し・その他特例・容積率不算入床面積はない。問10は比率による面積上限だけを計算し、斜線・高さ・避難・採光等を含む実際の建築可否は判定しない。問11の売却案と問12の店舗賃貸案は、実際に同時に行うものではない別々の仮定である。売却案では、相続後に家屋・土地を居住・事業・賃貸に使用せず、2026年8月1日に家屋全部を取り壊し、同年9月30日に土地全部を特別の関係のない第三者へ7,600万円で売るものとする。売却案では取壊し後も売却まで建物・構築物の敷地や駐車場等にせず、分割売却や他の相続人の売却はない。特別控除前の譲渡所得は計算済みの3,600万円とし、同じ被相続人の財産への同特例の過去適用・他特例との併用はなく、確認書等を添付した確定申告を含む他の必要要件も満たす。店舗案では、売却をせず遠藤さんがP社から返還義務のある建設協力金3,600万円を無利息で借り、自己所有の店舗を建築してP社に一棟全部を賃貸する。土地そのものをP社へ借地として貸す方式ではない。店舗案の契約賃料は月50万円、協力金元本の返済は月15万円で毎月相殺し、入金は月35万円とする。債務免除・返還不要部分・利息はなく、消費税等はこの設問では考慮しない。問12③の相続評価は、店舗が完成して通常の借家権の目的となり、店舗全体をP社へ継続賃貸中である別の課税時点の仮定とする。計画だけの段階・社宅・居住用区分所有財産ではなく、小規模宅地等の特例や個別の評価額・債務控除額は求めない。法令基準日は2026年4月1日に固定する。",
    "organization": "kinzai",
