    "sentences": [
      "木村Hさん（1953年10月15日生）は2026年4月1日に72歳で死亡し、関係者は全員同日に死亡を知った。法律上の妻Wさん（1956年10月2日生・69歳）、長男Sさん（1981年9月10日生・44歳）、長女Dさんの唯一の子Gさん（2001年12月5日生・24歳）がいる。",
      "長女Dさん（1983年5月20日生）は2023年11月30日に死亡している。他の子・養子・相続放棄・欠格・廃除はなく、GさんはDさんを代襲する。全員国内居住者である。",
      "有効な遺言等により、Wさんは現預金3,200万円、自宅敷地400㎡（特例適用前6,000万円）、自宅建物1,200万円を取得する。敷地の1㎡当たりの評価額は均一で、Hさんの居住用宅地全体をWさんが取得する。",
      "Wさんは、Hさんが保険料を全額負担しHさんを被保険者とする死亡保険金2,400万円の唯一の受取人でもある。他に死亡保険金を受け取る人はいない。",
      "Sさんは現預金3,000万円、Hさんが2010年から飲食店事業に使っていた敷地300㎡（特例適用前4,500万円）、店舗建物1,500万円を取得する。Sさんは申告期限前に事業を引き継ぎ、期限まで事業を続け土地を保有する。",
      "Gさんは現預金8,060万円を取得する。表の金額は相続税評価額で、建物に小規模宅地等の減額は行わない。相続開始前の贈与、相続時精算課税、債務、葬式費用、他の財産・控除はない。",
      "自宅敷地は特定居住用宅地等、店舗敷地は特定事業用宅地等の要件を満たす。貸付事業用宅地等はなく、個人事業用資産の納税猶予等との併用もない。両敷地について適用の選択・同意、明細や必要書類を添付する所定申告等の要件を満たす。",
      "財産の分割・取得は申告期限までに確定し、隠蔽・仮装財産はない。配偶者の税額軽減についても必要な書類を添付して申告する。妻の居住継続や保有継続を、本問の特定居住用宅地等における配偶者の追加要件として課してはいない。",
      "問15の課税遺産総額1億6,000万円は、小規模宅地等の特例・保険金非課税と基礎控除を反映した後の計算済みの金額である。再度基礎控除を差し引かない。各人への実際の税額配分や配偶者軽減後の最終納税額ではなく、法定相続分で仮計算する相続税の総額を求める。法令基準日は2026年4月1日。"
    ],
