      "svg": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 400 340\" width=\"400\" height=\"340\" role=\"img\" font-family=\"system-ui, sans-serif\"><title>厚生年金の期間区分</title><desc>2003年3月以前は84月、平均標準報酬月額250,000円。2003年4月以後は264月、平均標準報酬額400,000円。</desc><rect x=\"24\" y=\"20\" width=\"352\" height=\"130\" rx=\"8\" fill=\"#f3f7f9\" stroke=\"#253f50\" stroke-width=\"2\" /><text x=\"200\" y=\"49\" font-size=\"19\" font-weight=\"600\" text-anchor=\"middle\" fill=\"#172a3a\">2003年3月以前</text><text x=\"200\" y=\"84\" font-size=\"25\" font-weight=\"700\" text-anchor=\"middle\" fill=\"#172a3a\">84 月</text><text x=\"200\" y=\"111\" font-size=\"15\" font-weight=\"normal\" text-anchor=\"middle\" fill=\"#172a3a\">平均標準報酬月額</text><text x=\"200\" y=\"136\" font-size=\"20\" font-weight=\"600\" text-anchor=\"middle\" fill=\"#172a3a\">250,000 円</text><rect x=\"24\" y=\"190\" width=\"352\" height=\"130\" rx=\"8\" fill=\"#f3f7f9\" stroke=\"#253f50\" stroke-width=\"2\" /><text x=\"200\" y=\"219\" font-size=\"19\" font-weight=\"600\" text-anchor=\"middle\" fill=\"#172a3a\">2003年4月以後</text><text x=\"200\" y=\"254\" font-size=\"25\" font-weight=\"700\" text-anchor=\"middle\" fill=\"#172a3a\">264 月</text><text x=\"200\" y=\"281\" font-size=\"15\" font-weight=\"normal\" text-anchor=\"middle\" fill=\"#172a3a\">平均標準報酬額</text><text x=\"200\" y=\"306\" font-size=\"20\" font-weight=\"600\" text-anchor=\"middle\" fill=\"#172a3a\">400,000 円</text><line x1=\"200\" y1=\"150\" x2=\"200\" y2=\"179\" stroke=\"#253f50\" stroke-width=\"2\" /><path d=\"M 193 170 L 200 180 L 207 170\" fill=\"none\" stroke=\"#253f50\" stroke-width=\"2\" /></svg>",
