      "会社員の山田さん（1961年12月2日生まれ）は、2026年4月1日現在の制度で老後の資金計画と公的医療保険について相談している。",
      "健康保険は協会けんぽの被保険者である。",
      "65歳時の年金年額を2026年度価額で試算し、老齢基礎年金の満額は847,300円を用いる。",
