    "sourceText": "資料の相続税の課税価格計算における債務控除について、適切な説明はどれか。\n〈相続税の債務控除と実際の負担〉\n項目 / 条件\n相続開始 / 2026年3月1日に被相続人Aさんが死亡した\n当事者 / Aさんと相続人Bさんはいずれも日本国籍があり、相続開始時に日本国内に住所を有する。国外転出時課税の納税猶予等はない\n借入金 / Aさんが死亡時に現に負っていた、確実な未弁済の通常の住宅ローン債務\nBさんの取得と負担 / Bさんは相続により財産を取得し、その借入債務を実際に負担する\n除外する事情 / 団体信用生命保険による弁済・返済免除、ほかの免除、非課税財産に関する債務等はない\n範囲 / 所定要件を満たす借入債務を差し引く方向を問う。葬式費用等の個別の可否や国際課税の全条件は問わない\n独自設例。法令基準日は2026年4月1日。金額は資料の条件に限定します。",
